# region: digest
def digest(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
            return out
    return out

# region: sift
def sift(xs):
    return [v for v in xs if v % 2 == 0]

# region: shape
def shape(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: emit
def emit(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return emit(shape(sift(digest(raw))))

